def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

count = 0
p_list = []
n = 3  # Start checking from 3, as 2 is not 3 mod 4
target_count = 50

while count < target_count:
    if is_prime(n) and n % 4 == 3:
        count += 1
        p_list.append(n)
        if count == target_count:
            print(f"The {target_count}th prime p such that p = 3 (mod 4) is: {n}")
            break
    n += 2 # Only check odd numbers

